    ['TOTAL AMOUNT'],
    ['TOTAL DUE','AMOUNT DUE','BALANCE DUE','NETT TOTAL','NET TOTAL','TOTAL','AMOUNT'],
]

NUM_RE = re.compile(r'(\d{1,3}(?:,\d{3})*\.\d{2}|\d+\.\d{2})')

def ocr(path):
    img = Image.open(path)
    w,h = img.size
    variants = []
    g = ImageOps.grayscale(img)
    variants.append(ImageOps.autocontrast(g))
    big = img.resize((w*2,h*2), Image.LANCZOS)
    variants.append(ImageOps.autocontrast(ImageOps.grayscale(big)))
    variants.append(ImageOps.autocontrast(g).filter(ImageFilter.SHARPEN))
    texts = []
    for v in variants:
        for psm in ['--psm 6','--psm 4','--psm 11']:
            try:
                texts.append(pytesseract.image_to_string(v, config=psm))
            except: pass
    return texts

def parse_amount(text):
    lines = [l.strip() for l in text.splitlines() if l.strip()]
    for kwset in PRIORITY:
        for i,line in enumerate(lines):
            up = line.upper()
            if any(e in up for e in EXCLUDE): continue
            if any(k in up for k in kwset):
                nums = NUM_RE.findall(line)
                if nums:
                    return nums[-1].replace(',','')
                if i+1 < len(lines):
                    nums2 = NUM_RE.findall(lines[i+1])
                    if nums2:
                        return nums2[-1].replace(',','')
    return None

DATE_PATTERNS = [
    (re.compile(r'(\d{1,2})[-/](\d{1,2})[-/](\d{2,4})'), 'dmy'),
    (re.compile(r'(\d{4})[-/](\d{1,2})[-/](\d{1,2})'), 'ymd'),
]

def parse_date(text):
    for line in text.splitlines():
        for pat, order in DATE_PATTERNS:
            m = pat.search(line)
            if m:
                a,b,c = m.groups()
                try:
                    if order == 'ymd':
                        y,mo,d = int(a),int(b),int(c)
                    else:
                        d,mo,y = int(a),int(b),int(c)
                        if y < 100: y += 2000
                    if 1<=mo<=12 and 1<=d<=31 and 2000<=y<=2099:
                        return f'{y:04d}-{mo:02d}-{d:02d}'
                except: pass
    return None

def best_amount(texts):
    for lvl_idx in range(len(PRIORITY)):
        for t in texts:
