                    if i+1<len(lines):
                        nums2 = NUM_RE.findall(lines[i+1])
                        if nums2: return nums2[-1].replace(',','')
    return None

def best_date(texts):
    from collections import Counter
    cands = []
    for t in texts:
        d = parse_date(t)
        if d: cands.append(d)
    if cands:
        return Counter(cands).most_common(1)[0][0]
    return None

wb = Workbook()
